#!/bin/bash
#SBATCH --nodes=1
#SBATCH --cpus-per-task=8
#SBATCH --time=24:00:00
#SBATCH --output=/cluster/scratch/gsialelli/logs/pangaea-%A_%a.txt
#SBATCH --error=/cluster/scratch/gsialelli/logs/pangaea-%A_%a.txt
#SBATCH --mem-per-cpu=8G
#SBATCH --job-name=pangaea-geotest
#SBATCH --gpus=rtx_4090:1
#SBATCH --array=1-3

# GENERATED by benchmark_pangaea/testfull_runs/lora_holdout/gen.py -- edit that, not this.
# Usage (from the pangaea-bench checkout): sbatch $0 general|cross|within

MODE=$1
REGIONS=(SouthAsia Africa SouthAmerica)
TEST_REGIONS=('South Asia' 'Africa' 'South America')
CROSS_RUNS=(RUN_DIR_cross_SouthAsia RUN_DIR_cross_Africa RUN_DIR_cross_SouthAmerica)
WITHIN_RUNS=(RUN_DIR_within_SouthAsia RUN_DIR_within_Africa RUN_DIR_within_SouthAmerica)
T=$((SLURM_ARRAY_TASK_ID-1))
REGION=${REGIONS[$T]}
case "$MODE" in
    general) CKPT=20260930_080105_f8cb5c_terramind_tiny_lora_reg_upernet_agbd ;;
    cross)   CKPT=${CROSS_RUNS[$T]} ;;
    within)  CKPT=${WITHIN_RUNS[$T]} ;;
    *) echo "usage: sbatch $0 general|cross|within"; exit 1 ;;
esac
case "$CKPT" in RUN_DIR_*) echo "configs/full_lora_holdout.txt still has the placeholder $CKPT: fill it and rerun gen.py"; exit 1 ;; esac
echo "Mode: $MODE   region: $REGION   checkpoint: $CKPT"

grep -q "test_region" pangaea/datasets/agbd.py || { echo "pangaea/datasets/agbd.py has no test_region: pull pangaea-bench first"; exit 1; }
[ -f "$CKPT/configs/config.yaml" ] || { echo "$CKPT/configs/config.yaml missing"; exit 1; }
ls "$CKPT"/*_best.pth > /dev/null 2>&1 || { echo "no *_best.pth in $CKPT"; exit 1; }

SHADOW=${CKPT}_test-${REGION}
mkdir -p "$SHADOW"
ln -sfn "$(realpath "$CKPT/configs")" "$SHADOW/configs"
for f in "$CKPT"/*.pth; do ln -sfn "$(realpath "$f")" "$SHADOW/$(basename "$f")"; done
echo "Shadow run directory: $SHADOW"

# Move all of the necessary data to $TMPDIR (the same files and sources as trainfull_runs/,
# minus AGBD-Lite-val.h5, which only validation reads)
rclone copy /cluster/work/igp_psr/gsialelli/Data/patches/ ${TMPDIR} --include "*v4_*-20.h5" --transfers 16 --checkers 32
# biomes_splits_to_name.pkl
cp /cluster/work/igp_psr/gsialelli/Data/AGB/biomes_splits_to_name.pkl ${TMPDIR}
# 'tiles_per_region.pkl'
cp /cluster/work/igp_psr/gsialelli/EcosystemAnalysis/Models/Biomes/helper/tiles_per_region.pkl ${TMPDIR}
# 'AEF_overlaps.pkl'
cp /cluster/work/igp_psr/gsialelli/AGBD-GFM/aef-dwn/AEF_overlaps.pkl ${TMPDIR}

# Refuse to start on an incomplete copy: the exact files pangaea's AGBD opens (agbd.py fnames)
for f in biomes_splits_to_name.pkl tiles_per_region.pkl AEF_overlaps.pkl          data_subset-{2019,2020}-v4_{0..19}-20.h5; do
    if [ ! -f "${TMPDIR}/$f" ]; then echo "staging: ${TMPDIR}/$f is missing" >&2; exit 1; fi
done

AGBD_DUMP_H5=$(realpath "$SHADOW")/full_test_${REGION}.h5 HYDRA_FULL_ERROR=1 TQDM_DISABLE=1 torchrun --rdzv-backend=c10d --rdzv-endpoint=localhost:0 --nnodes=1 --nproc_per_node=1 pangaea/run.py --config-name=test ckpt_dir=$SHADOW "++test_overrides.dataset.test_region=${TEST_REGIONS[$T]}" ++test_overrides.dataset.root_path_cluster=${TMPDIR} ++test_overrides.use_wandb=false ++test_overrides.task.trainer.use_wandb=false ++test_overrides.task.evaluator.use_wandb=false
